interface.definition:
a!localVariables(
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!ismemberofusergroup:or(
    contains(
    touniformstring(local!userBU),
    tostring(ri!nomination.originatingBU)
  ),
  contains(
    touniformstring(local!userBU),
    tostring(ri!nomination.returnBU)
  ),
  a!isNullOrEmpty(local!userBU)),
  if(
    local!ismemberofusergroup,
    {
      #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3781239"(
        reportName: "Nomination Home",
        report: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_4046414",
        recordName: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6677441"(
          nominationTypeId: ri!nomination.nominationTypeId,
          originatingBU: ri!nomination.originatingBU,
          firstName: ri!nomination.firstName,
          lastName: ri!nomination.lastName
        )
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        marginBelow: "STANDARD",
        showShadow: true,
        style: "ACCENT",
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(width: "EXTRA_NARROW"),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    label: "Status",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: index(
                        ri!nomination,
                        "nominationStatus",
                        tostring(null)
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    label: "Last Modified By",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: if(
                        length(
                          split(
                            index(
                              ri!nomination,
                              "modifiedBy",
                              tostring(null)
                            ),
                            " "
                          )
                        ) = 1,
                        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(
                          user: index(
                            ri!nomination,
                            "modifiedBy",
                            tostring(null)
                          )
                        ),
                        index(
                          ri!nomination,
                          "modifiedBy",
                          tostring(null)
                        )
                      )
                    )
                  )
                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    label: "Last Modified On",
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: index(
                        ri!nomination,
                        "modifiedOn",
                        tostring(null)
                      )
                    )
                  )
                }
              )
            }
          )
        }
      ),
      /*CANDIDATE SELECTION*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Candidate Selection",
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                showWhen: property(
                  ri!nomination,
                  "nominationTypeId",
                  tointeger(null)
                ) <> #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
                contents: {
                  #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3643244"(nominationView: ri!nomination)
                },
                width: "NARROW_PLUS"
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  if(
                    property(
                      ri!nomination,
                      "nominationTypeId",
                      tointeger(null)
                    ) = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
                    #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3842998"(
                      isReadOnly: true,
                      nominationView: ri!nomination
                    ),
                    if(
                      ri!nomination.isDirectHire = true,
                      #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6660854"(nominationView: ri!nomination),
                      #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3662875"(nominationView: ri!nomination)
                    )
                  )
                }
              )
            }
          )
        },
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      ),
      /*FURTHER DETAILS SELECTION*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Further Candidate Details",
        contents: {
          if(
            property(
              ri!nomination,
              "nominationTypeId",
              tointeger(null)
            ) = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3843030"(
              nominationView: ri!nomination,
              isReadOnly: true
            ),
            #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3643804"(
              candidateClients: #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14141386"(
                nominationId: ri!nomination.nominationId,
                pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(
                  startIndex: 1,
                  batchSize: - 1,
                  sort: #"SYSTEM_SYSRULES_sortInfo"(field: "clientId", ascending: true)
                ),

              ),
              nominationView: ri!nomination,
              showWhen: true
            )
          )
        },
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      ),
      /*ROLE*/
      #"SYSTEM_SYSRULES_sectionLayout_v1"(
        label: "Role",
        contents: {
          if(
            property(
              ri!nomination,
              "nominationTypeId",
              tointeger(null)
            ) = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
            #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3851745"(
              nominationView: ri!nomination,
              isReadOnly: true
            ),
            #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3665144"(nominationView: ri!nomination)
          )
        },
        showWhen: or(
          property(ri!nomination, "isDirectHire", null) = false,
          #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
            property(ri!nomination, "isDirectHire", null)
          )
        ),
        isCollapsible: true,
        divider: "ABOVE",
        dividerWeight: "MEDIUM",
        dividerColor: "ACCENT",
        marginBelow: "STANDARD"
      )
    },
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      contents: #"SYSTEM_SYSRULES_cardLayout"(
        contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
          value: #"SYSTEM_SYSRULES_richTextItem_v1"(
            text: "You are not able to view this nomination because you are not a part of the  " & touniformstring(ri!nomination.originatingBU) &" Group", 
            style: "STRONG",
            size: "MEDIUM",

          )
        )
      )
    ),

  )
)
